import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Sonner from "../../ui/sonner";

const ToastVariant = S.Union([
  S.Literal("default"),
  S.Literal("success"),
  S.Literal("info"),
  S.Literal("warning"),
  S.Literal("error"),
]);
const ToastPosition = S.Union([
  S.Literal("top-left"),
  S.Literal("top-center"),
  S.Literal("top-right"),
  S.Literal("bottom-left"),
  S.Literal("bottom-center"),
  S.Literal("bottom-right"),
]);

// MODEL

export const Model = S.Struct({
  visible: S.Boolean,
  variant: ToastVariant,
  position: ToastPosition,
});
export type Model = typeof Model.Type;

// MESSAGE

export const ClickedShowToast = m("ClickedShowToast");
export const ClickedDismissToast = m("ClickedDismissToast");
export const SelectedToastVariant = m("SelectedToastVariant", {
  value: ToastVariant,
});
export const SelectedToastPosition = m("SelectedToastPosition", {
  value: ToastPosition,
});
export const Message = S.Union([
  ClickedShowToast,
  ClickedDismissToast,
  SelectedToastVariant,
  SelectedToastPosition,
]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ visible: false, variant: "default", position: "bottom-right" }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedShowToast: () => [evo(model, { visible: () => true }), []],
      ClickedDismissToast: () => [evo(model, { visible: () => false }), []],
      SelectedToastVariant: ({ value }) => [
        evo(model, { visible: () => true, variant: () => value }),
        [],
      ],
      SelectedToastPosition: ({ value }) => [
        evo(model, { visible: () => true, position: () => value }),
        [],
      ],
    })
  );

// VIEW

const variantLabel = (variant: Model["variant"]): string =>
  ({
    default: "Default",
    success: "Success",
    info: "Info",
    warning: "Warning",
    error: "Error",
  })[variant];

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("min-h-64 space-y-4")],
    [
      h.div(
        [h.Class("flex flex-wrap gap-2")],
        [
          h.button(
            [
              h.Type("button"),
              h.OnClick(ClickedShowToast()),
              h.Class(
                "rounded-md bg-gray-950 px-4 py-2 text-sm font-medium text-white"
              ),
            ],
            ["Show toast"]
          ),
          ...(["default", "success", "info", "warning", "error"] as const).map(
            (variant) =>
              h.button(
                [
                  h.Type("button"),
                  h.OnClick(SelectedToastVariant({ value: variant })),
                  h.Class("rounded-md border px-3 py-2 text-sm"),
                ],
                [variantLabel(variant)]
              )
          ),
        ]
      ),
      h.div(
        [h.Class("flex flex-wrap gap-2")],
        (
            [
              "top-left",
              "top-center",
              "top-right",
              "bottom-left",
              "bottom-center",
              "bottom-right",
            ] as const
          ).map((position) =>
            h.button(
              [
                h.Type("button"),
                h.OnClick(SelectedToastPosition({ value: position })),
                h.Class("rounded-md border px-3 py-2 text-sm"),
              ],
              [position.replace("-", " ")]
            )
          )
      ),
      Sonner.viewportView<Message>({
        position: model.position,
        children: model.visible
          ? [
              Sonner.toastView<Message>({
                title:
                  model.variant === "default"
                    ? "Event has been created"
                    : `${variantLabel(model.variant)} toast`,
                description: "Sunday, December 03, 2023 at 9:00 AM",
                variant: model.variant,
                onClose: ClickedDismissToast(),
              }),
            ]
          : [],
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as SonnerBasicExample from "./main";

describe("Sonner Basic example", () => {
  test("shows and dismisses a toast", () => {
    Scene.scene(
      {
        update: SonnerBasicExample.update,
        view: SonnerBasicExample.view,
      },
      Scene.with(SonnerBasicExample.init()[0]),
      Scene.expect(Scene.role("status")).toBeAbsent(),
      Scene.click(Scene.role("button", { name: "Show toast" })),
      Scene.expect(Scene.role("status")).toExist(),
      Scene.expect(Scene.text("Event has been created")).toExist(),
      Scene.expect(
        Scene.text("Sunday, December 03, 2023 at 9:00 AM")
      ).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.expect(Scene.role("status")).toBeAbsent()
    );
  });

  test("shows type and position variants", () => {
    Scene.scene(
      {
        update: SonnerBasicExample.update,
        view: SonnerBasicExample.view,
      },
      Scene.with(SonnerBasicExample.init()[0]),
      Scene.click(Scene.role("button", { name: "Success" })),
      Scene.expect(Scene.text("Success toast")).toExist(),
      Scene.expect(Scene.role("img", { name: "Success icon" })).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "Info" })),
      Scene.expect(Scene.text("Info toast")).toExist(),
      Scene.expect(Scene.role("img", { name: "Info icon" })).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "Warning" })),
      Scene.expect(Scene.text("Warning toast")).toExist(),
      Scene.expect(Scene.role("img", { name: "Warning icon" })).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "Error" })),
      Scene.expect(Scene.text("Error toast")).toExist(),
      Scene.expect(Scene.role("img", { name: "Error icon" })).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "Default" })),
      Scene.expect(Scene.text("Event has been created")).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "top left" })),
      Scene.expect(Scene.text("Event has been created")).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss toast" })),
      Scene.click(Scene.role("button", { name: "bottom center" })),
      Scene.expect(Scene.text("Event has been created")).toExist()
    );
  });
});
